// Booking request summary (PDF). Called by js/booking.js after the request has been sent.
// Input is the array built by the booking form:
//   [ { contactName, contactEmail, contactPersonMobNo, arrivalTime, requirementSpec },
//     [checkIn, checkOut],
//     ["villa1", adults, children] ]
// It is a reference document, not a confirmation: the host confirms availability first.
(function (global) {
    'use strict';

    var BUSINESS = {
        name: 'Black and White Stays',
        place: 'Kalpetta, Wayanad, Kerala, India',
        site: 'www.bwstays.com',
        email: 'bwstays@gmail.com'
    };
    // Estimate only: rates are as listed on the booking page; extra guests as per the site's occupancy rule.
    // data/rates.js (loaded before this file) is the single source of the rates; the fallback below only guards a failed load.
    var R0 = global.bwRates || { perNight: 2100, includedAdults: 4, includedChildren: 1, extraChildPerNight: 800 };
    var RATE = { perNight: R0.perNight, includedAdults: R0.includedAdults, includedChildren: R0.includedChildren, includedTotal: R0.includedAdults + R0.includedChildren, extraChild: R0.extraChildPerNight };
    var TEAL = [63, 127, 123];
    var INK = [33, 37, 41];
    var MUTED = [108, 117, 125];
    var HAIR = [222, 226, 230];

    var QR = 'data:image/jpeg;base64,';

    function inr(n) {
        return 'Rs. ' + Math.round(n).toLocaleString('en-IN');
    }

    function parseDay(value) {
        var m = String(value || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
        return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
    }

    function longDate(d) {
        return d ? d.toLocaleDateString('en-GB', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }) : '-';
    }

    function reference(now) {
        var pad = function (n) { return String(n).padStart(2, '0'); };
        var rand = Math.random().toString(36).slice(2, 5).toUpperCase();
        return 'BW-' + now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes()) + '-' + rand;
    }

    function villaRow(label, spec, nights) {
        var adults = Number(spec[1]) || 0;
        var children = Number(spec[2]) || 0;
        // an extra bed is charged for each child beyond the included child (the booking form allows up to 4 adults and 4 children)
        var extraChildren = Math.max(0, children - RATE.includedChildren);
        var extraPerNight = extraChildren * RATE.extraChild;
        var perNight = RATE.perNight + extraPerNight;
        return {
            villa: label,
            guests: adults + ' adult' + (adults === 1 ? '' : 's') + ', ' + children + ' child' + (children === 1 ? '' : 'ren'),
            nights: nights,
            rate: RATE.perNight,
            extra: extraPerNight,
            amount: perNight * nights
        };
    }

    function invokeRefBooking(myArray) {
        var jsPDF = global.jspdf && global.jspdf.jsPDF;
        if (!jsPDF) {
            throw new Error('PDF library not loaded');
        }
        var guest = myArray[0] || {};
        var dates = myArray[1] || [];
        var checkIn = parseDay(dates[0]);
        var checkOut = parseDay(dates[1]);
        var nights = checkIn && checkOut ? Math.max(1, Math.round((checkOut - checkIn) / 86400000)) : 1;
        var rows = [];
        if (myArray[2] && myArray[2].length) rows.push(villaRow('Villa Stay', myArray[2], nights));
        var subtotal = rows.reduce(function (s, r) { return s + r.amount; }, 0);
        var total = subtotal; // fees are quoted inclusive of GST (Terms)
        var now = new Date();
        var ref = reference(now);

        var pdf = new jsPDF({ unit: 'mm', format: 'a4' });
        var W = pdf.internal.pageSize.getWidth();
        var H = pdf.internal.pageSize.getHeight();
        var L = 15;
        var R = W - 15;
        var y = 0;

        pdf.setProperties({
            title: 'Booking request ' + ref,
            subject: 'Booking request - Black and White Stays',
            author: BUSINESS.name,
            creator: BUSINESS.site
        });

        function text(str, x, yy, opts) {
            pdf.text(String(str == null ? '' : str), x, yy, opts || {});
        }
        function label(str, x, yy) {
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(8);
            pdf.setTextColor.apply(pdf, MUTED);
            text(str.toUpperCase(), x, yy);
        }
        function value(str, x, yy, bold) {
            pdf.setFont('helvetica', bold ? 'bold' : 'normal');
            pdf.setFontSize(10);
            pdf.setTextColor.apply(pdf, INK);
            text(str, x, yy);
        }
        function rule(yy) {
            pdf.setDrawColor.apply(pdf, HAIR);
            pdf.setLineWidth(0.3);
            pdf.line(L, yy, R, yy);
        }

        // ---- header band
        pdf.setFillColor.apply(pdf, TEAL);
        pdf.rect(0, 0, W, 4, 'F');
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(15);
        pdf.setTextColor.apply(pdf, INK);
        text('BLACK & WHITE', L, 17);
        pdf.setFontSize(9);
        pdf.setFont('helvetica', 'normal');
        pdf.setTextColor.apply(pdf, TEAL);
        text('S T A Y S   -   K A L P E T T A ,  W A Y A N A D', L, 23);
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(18);
        pdf.setTextColor.apply(pdf, TEAL);
        text('Booking request', R, 17, { align: 'right' });
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(9);
        pdf.setTextColor.apply(pdf, MUTED);
        text('Reference ' + ref, R, 23, { align: 'right' });
        text('Requested on ' + longDate(now), R, 28, { align: 'right' });
        y = 34;
        rule(y);

        // ---- guest and property, two aligned columns
        y += 9;
        var colB = W / 2 + 5;
        label('Guest', L, y);
        label('Property', colB, y);
        y += 6;
        value(guest.contactName || '-', L, y, true);
        value(BUSINESS.name, colB, y, true);
        y += 5.5;
        value(guest.contactEmail || '-', L, y);
        value(BUSINESS.place, colB, y);
        y += 5.5;
        value(guest.contactPersonMobNo || '-', L, y);
        value(BUSINESS.site, colB, y);
        y += 5.5;
        value(BUSINESS.email, colB, y);
        y += 9;
        var notes = pdf.splitTextToSize(guest.requirementSpec || '', R - L);
        if (notes.length && notes[0]) {
            label('Address and requests', L, y);
            y += 5.5;
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(10);
            pdf.setTextColor.apply(pdf, INK);
            text(notes.slice(0, 3), L, y);
            y += 5 * Math.min(notes.length, 3);
        }
        y += 6;

        // ---- stay summary: four equal cells
        pdf.setFillColor(246, 248, 248);
        pdf.roundedRect(L, y, R - L, 22, 2, 2, 'F');
        var cell = (R - L) / 4;
        var cells = [
            ['Check-in', longDate(checkIn)],
            ['Check-out', longDate(checkOut)],
            ['Nights', String(nights)],
            ['Arrival time', guest.arrivalTime || '-']
        ];
        cells.forEach(function (c, i) {
            var x = L + 5 + i * cell;
            label(c[0], x, y + 8);
            value(c[1], x, y + 15, true);
        });
        y += 30;

        // ---- price table
        pdf.autoTable({
            startY: y,
            head: [['Villa', 'Guests', 'Nights', 'Rate / night', 'Extra guests / night', 'Amount']],
            body: rows.map(function (r) {
                return [r.villa, r.guests, String(r.nights), inr(r.rate), r.extra ? inr(r.extra) : '-', inr(r.amount)];
            }),
            theme: 'plain',
            margin: { left: L, right: W - R },
            styles: { font: 'helvetica', fontSize: 9.5, textColor: INK, cellPadding: { top: 3, bottom: 3, left: 2, right: 2 }, lineColor: HAIR, lineWidth: 0 },
            headStyles: { fillColor: TEAL, textColor: 255, fontStyle: 'bold', fontSize: 8.5 },
            bodyStyles: { lineWidth: { bottom: 0.2 }, lineColor: HAIR },
            columnStyles: {
                0: { cellWidth: 42 },
                1: { cellWidth: 36 },
                2: { halign: 'right', cellWidth: 16 },
                3: { halign: 'right', cellWidth: 28 },
                4: { halign: 'right', cellWidth: 34 },
                5: { halign: 'right', cellWidth: 24, fontStyle: 'bold' }
            },
            didParseCell: function (data) {
                if (data.section === 'head' && data.column.index >= 2) data.cell.styles.halign = 'right';
            }
        });
        y = pdf.lastAutoTable.finalY + 6;

        // ---- totals, right aligned on the same edge as the table
        var tx = R - 72;
        function totalRow(name, amt, strong) {
            pdf.setFont('helvetica', strong ? 'bold' : 'normal');
            pdf.setFontSize(strong ? 11 : 10);
            pdf.setTextColor.apply(pdf, strong ? TEAL : INK);
            text(name, tx, y);
            text(amt, R, y, { align: 'right' });
            y += strong ? 7 : 5.5;
        }
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor.apply(pdf, MUTED);
        text('Extra child per night: ' + inr(RATE.extraChild) + ' for each child beyond ' + RATE.includedChildren + ' (up to 4 children in all).', R, y - 1, { align: 'right' });
        y += 6;
        pdf.setDrawColor.apply(pdf, TEAL);
        pdf.setLineWidth(0.4);
        pdf.line(tx, y - 3, R, y - 3);
        y += 1.5;
        totalRow('Estimated total', inr(total), true);
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor.apply(pdf, MUTED);
        text('Estimate from the listed rate, GST included; the host confirms the final amount.', R, y, { align: 'right' });
        y += 10;

        // ---- status box
        var status = [
            'This is a request, not a confirmation.',
            'We check availability and reply by email, usually within a day. Your dates are held once we confirm,',
            'and a payment request follows. Please do not pay before you receive our confirmation.'
        ];
        var boxH = 24;
        if (y + boxH > H - 70) { pdf.addPage(); y = 20; }
        pdf.setFillColor(255, 248, 230);
        pdf.setDrawColor(232, 200, 114);
        pdf.setLineWidth(0.4);
        pdf.roundedRect(L, y, R - L, boxH, 2, 2, 'FD');
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(10.5);
        pdf.setTextColor(122, 90, 0);
        text(status[0], L + 5, y + 8);
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(9);
        pdf.setTextColor.apply(pdf, INK);
        text(status[1], L + 5, y + 14);
        text(status[2], L + 5, y + 19);
        y += boxH + 10;

        // ---- next steps (left) and payment QR (right), side by side
        var stepsW = R - L - 52;
        label('What happens next', L, y);
        var sy = y + 6;
        var steps = [
            '1.  We confirm availability for your dates and reply to ' + (guest.contactEmail || 'your email') + '.',
            '2.  After confirmation we send the payment request.',
            '3.  Cancellation terms: ' + BUSINESS.site + '/footer.html#cancellation',
            '4.  Questions: ' + BUSINESS.email
        ];
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(9.5);
        pdf.setTextColor.apply(pdf, INK);
        steps.forEach(function (s) {
            var lines = pdf.splitTextToSize(s, stepsW);
            text(lines, L, sy);
            sy += 5.2 * lines.length + 1.5;
        });
        if (QR) {
            var qx = R - 40;
            label('Payment', qx, y);
            try {
                pdf.addImage(QR, 'JPEG', qx, y + 3, 40, 40);
                pdf.setFont('helvetica', 'normal');
                pdf.setFontSize(7.5);
                pdf.setTextColor.apply(pdf, MUTED);
                text('Only after you receive our', qx + 20, y + 47, { align: 'center' });
                text('confirmation. Quote ' + ref, qx + 20, y + 51, { align: 'center' });
            } catch (e) { /* the payment image is optional */ }
        }

        // ---- footer on every page
        var pages = pdf.internal.getNumberOfPages();
        for (var i = 1; i <= pages; i++) {
            pdf.setPage(i);
            pdf.setDrawColor.apply(pdf, HAIR);
            pdf.setLineWidth(0.3);
            pdf.line(L, H - 14, R, H - 14);
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(8);
            pdf.setTextColor.apply(pdf, MUTED);
            text(BUSINESS.name + '  |  ' + BUSINESS.site, L, H - 9);
            text('Page ' + i + ' of ' + pages, R, H - 9, { align: 'right' });
        }

        pdf.save('bwBookingRequest-' + ref + '.pdf');
    }

    global.invokeRefBooking = invokeRefBooking;
})(window);
